import React from 'react';
import type { CRadioGroupOption } from '@cloud-materials/common';
import { Button, CRadio } from '@cloud-materials/common';

const RadioGroup = CRadio.Group;

const statusOptions: CRadioGroupOption[] = [
  {
    value: 'Beijing',
    label: '公共镜像',
  },
  {
    value: 'Beijing2',
    label: '公共镜像',
  },
  {
    value: 'Beijing3',
    label: '公共镜像',
    disabled: true,
  },
  {
    value: 'Beijing4',
    label: '公共镜像公共镜像',
  },
];

export default () => {
  return (
    <>
      <h3>可以通过传入函数类型的 children 来自定义渲染单选节点。</h3>
      <RadioGroup defaultValue={'Beijing'} type="radio">
        {statusOptions.map((p: { value: string; label: string }) => (
          <CRadio value={p.value} key={p.value}>
